import React, { useEffect, useState } from "react";
import {
  HashRouter as Router,
  Routes,
  Route,
  Navigate,
  Link as RouterLink,
} from "react-router-dom";
import ReactGA from "react-ga4";

import GraphDataHandler from "../components/GraphDataHandler";
import {
  CssBaseline,
  Container,
  Box,
  createTheme,
  darkScrollbar,
  ThemeProvider,
  IconButton,
  Tooltip,
  Link,
  Button,
  Stack,
  Typography,
} from "@mui/material";
import LightModeOutlinedIcon from "@mui/icons-material/LightModeOutlined";
import DarkModeOutlinedIcon from "@mui/icons-material/DarkModeOutlined";
import GitHubIcon from "@mui/icons-material/GitHub";

const GraphHome: React.FC = () => (
  <Stack
    spacing={2}
    sx={{ minHeight: "100vh", alignItems: "center", justifyContent: "center" }}
  >
    <Typography variant="h4">Narrative communities</Typography>
    <Typography color="text.secondary">
      Entity graphs from the fake-news and real-news corpora.
    </Typography>
    <Stack direction="row" spacing={2}>
      <Button component={RouterLink} to="/fake" variant="contained">
        Fake
      </Button>
      <Button component={RouterLink} to="/real" variant="contained">
        Real
      </Button>
    </Stack>
  </Stack>
);

const App: React.FC = () => {
  const [darkMode, setDarkMode] = useState(true);
  const paletteType = darkMode ? "dark" : "light";

  const theme = createTheme({
    palette: {
      mode: paletteType,
    },
    components: {
      MuiCssBaseline: {
        styleOverrides: {
          body: paletteType === "dark" ? darkScrollbar() : null,
        },
      },
      MuiPopover: {
        styleOverrides: {
          root: {
            zIndex: 1600,
          },
        },
      },
      MuiModal: {
        styleOverrides: {
          root: {
            zIndex: 1600,
          },
        },
      },
    },
  });

  function handleThemeChange() {
    setDarkMode(!darkMode);
    localStorage.setItem("theme", darkMode ? "light" : "dark");
  }

  useEffect(() => {
    const currentTheme = localStorage.getItem("theme");
    setDarkMode(currentTheme === "dark");
  }, []);

  useEffect(() => {
    const measurementId = process.env.REACT_APP_GA_MEASUREMENT_ID;
    if (measurementId) {
      ReactGA.initialize(measurementId);
      ReactGA.send({
        hitType: "pageview",
        page: window.location.pathname + window.location.search,
      });
    } else {
      console.error("Google Analytics measurement ID not found");
    }
  }, []);

  return (
    <ThemeProvider theme={theme}>
      <Router>
        <Container disableGutters maxWidth={false}>
          <CssBaseline />

          <Box
            sx={{
              position: "absolute",
              top: 12,
              right: 12,
              zIndex: 1000,
              display: "flex",
              flexDirection: { xs: "column", sm: "row" },
              alignItems: "center",
              gap: 1,
              padding: { xs: "20px 0px", sm: "0" },
            }}
          >
            <Button component={RouterLink} to="/fake" color="inherit" size="small">
              Fake
            </Button>
            <Button component={RouterLink} to="/real" color="inherit" size="small">
              Real
            </Button>
            <IconButton
              component={Link}
              href="https://github.com/upb-nlp/narrative-communities"
              target="_blank"
              rel="noopener"
              color="inherit"
            >
              <GitHubIcon />
            </IconButton>
            {darkMode ? (
              <Tooltip title="Turn on the light">
                <IconButton onClick={handleThemeChange} color="inherit">
                  <DarkModeOutlinedIcon />
                </IconButton>
              </Tooltip>
            ) : (
              <Tooltip title="Turn off the light">
                <IconButton onClick={handleThemeChange} color="inherit">
                  <LightModeOutlinedIcon />
                </IconButton>
              </Tooltip>
            )}
          </Box>
          <Routes>
            <Route path="/" element={<GraphHome />} />
            <Route path="/claims/original" element={<GraphDataHandler />} />
            <Route path="/claims/original/data" element={<GraphDataHandler />} />
            <Route path="/claims/merged" element={<GraphDataHandler />} />
            <Route path="/claims/merged/data" element={<GraphDataHandler />} />
            <Route path="/entities" element={<GraphDataHandler />} />
            <Route path="/fake" element={<GraphDataHandler />} />
            <Route path="/real" element={<GraphDataHandler />} />
            <Route path="/upload" element={<GraphDataHandler />} />
            <Route path="/graph" element={<Navigate to="/entities" replace />} />
            <Route path="/data" element={<GraphDataHandler />} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>

          {/* <GraphDataHandler /> */}
        </Container>
      </Router>
    </ThemeProvider>
  );
};

export default App;
