import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Entity } from "../models/entity";
import { Relationship } from "../models/relationship";
import { Document } from "../models/document";
import { TextUnit } from "../models/text-unit";
import { Community } from "../models/community";
import { CommunityReport } from "../models/community-report";
import { Covariate } from "../models/covariate";
import { ClaimClusterRow } from "../models/claim-cluster";
import { ClaimPairAuditRow } from "../models/claim-pair-audit";
import { readParquetFile } from "../utils/parquet-utils";

const baseFileNames = [
  "entities.parquet",
  "relationships.parquet",
  "documents.parquet",
  "text_units.parquet",
  "communities.parquet",
  "community_reports.parquet",
  "covariates.parquet",
];

const baseMapping: { [key: string]: string } = {
  "entities.parquet": "entity",
  "relationships.parquet": "relationship",
  "documents.parquet": "document",
  "text_units.parquet": "text_unit",
  "communities.parquet": "community",
  "community_reports.parquet": "community_report",
  "covariates.parquet": "covariate",
  "claim_clusters.parquet": "claim_cluster",
  "claim_pair_audit.parquet": "claim_pair_audit",
};

export const ARTIFACT_DATASETS: Record<string, string> = {
  "claims-original": "claims-original",
  "claims-merged": "claims-merged",
  claims: "claims-merged",
  fake: "fake",
  real: "real",
  real_qwen36: "real_qwen36",
  new_fake_news_36: "new_fake_news_36",
  default: "",
};

/** Default artifact bundle (combined fake-and-real entity graph). */
export const DEFAULT_ARTIFACT_DATASET = "new_all_qwen_36";

const datasetDir = (dataset: string) => {
  const slug = ARTIFACT_DATASETS[dataset] ?? dataset;
  const base = (process.env.PUBLIC_URL || "").replace(/\/$/, "");
  return slug ? `${base}/artifacts/${slug}` : `${base}/artifacts`;
};

const fileSchemas: { [key: string]: string } = {};
Object.entries(baseMapping).forEach(([key, value]) => {  
  fileSchemas[key] = value;  
  fileSchemas[`create_final_${key}`] = value;
});

const normalizeForHeuristic = (text: string) =>
  text
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();

const hasRepeatedNGram = (words: string[], n: number, threshold: number): boolean => {
  const counts = new Map<string, number>();
  for (let i = 0; i <= words.length - n; i += 1) {
    const gram = words.slice(i, i + n).join(" ");
    const next = (counts.get(gram) || 0) + 1;
    counts.set(gram, next);
    if (next >= threshold) return true;
  }
  return false;
};

const isLikelyMalformedEntityTitle = (title: string | undefined): boolean => {
  const raw = (title || "").trim();
  if (!raw) return true;
  if (raw.length > 180) return true;
  if (/[\u0400-\u04FF]/.test(raw)) return true; // Exclude Cyrillic-script artifacts.

  const normalized = normalizeForHeuristic(raw);
  const words = normalized.split(" ").filter(Boolean);
  if (words.length > 24) return true;

  // Catch run-on extraction artifacts like "... SI IN TIMPUL PANDEMIEI ..." repeated.
  const pandemicRepeats = normalized.match(/IN TIMPUL PANDEMIEI/g)?.length || 0;
  if (pandemicRepeats >= 2) return true;

  // Catch repeated phrase loops generated by bad extraction.
  if (hasRepeatedNGram(words, 3, 3) || hasRepeatedNGram(words, 4, 3)) return true;

  return false;
};

const sanitizeEntities = (entities: Entity[]): Entity[] => {
  const filtered = entities.filter((entity) => !isLikelyMalformedEntityTitle(entity.title));
  const removed = entities.length - filtered.length;
  if (removed > 0) {
    console.warn(`Filtered ${removed} malformed entity titles before visualization.`);
  }
  return filtered;
};

const useFileHandler = () => {
  const navigate = useNavigate();
  const [entities, setEntities] = useState<Entity[]>([]);
  const [relationships, setRelationships] = useState<Relationship[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [textunits, setTextUnits] = useState<TextUnit[]>([]);
  const [communities, setCommunities] = useState<Community[]>([]);
  const [covariates, setCovariates] = useState<Covariate[]>([]);
  const [claimClusters, setClaimClusters] = useState<ClaimClusterRow[]>([]);
  const [claimPairAudit, setClaimPairAudit] = useState<ClaimPairAuditRow[]>([]);
  const [communityReports, setCommunityReports] = useState<CommunityReport[]>(
    []
  );

  const handleFilesRead = async (files: File[]) => {
    await loadFiles(files);
  };

  const loadFiles = async (files: File[] | string[]) => {
    const entitiesArray: Entity[][] = [];
    const relationshipsArray: Relationship[][] = [];
    const documentsArray: Document[][] = [];
    const textUnitsArray: TextUnit[][] = [];
    const communitiesArray: Community[][] = [];
    const communityReportsArray: CommunityReport[][] = [];
    const covariatesArray: Covariate[][] = [];
    const claimClustersArray: ClaimClusterRow[][] = [];
    const claimPairAuditArray: ClaimPairAuditRow[][] = [];

    for (const file of files) {
      const fileName =
        typeof file === "string" ? file.split("/").pop()! : file.name;      
      const schema = fileSchemas[fileName] || fileSchemas[`create_final_${fileName}`];

      let data;
      if (typeof file === "string") {
        // Fetch default file from public folder as binary data
        const response = await fetch(file);
        if (!response.ok) {
          console.error(`Failed to fetch file ${file}: ${response.statusText}`);
          continue;
        }

        // Convert ArrayBuffer to File object
        const buffer = await response.arrayBuffer();
        const blob = new Blob([buffer], { type: "application/x-parquet" });
        const fileBlob = new File([blob], fileName);

        // Use the File object in readParquetFile
        data = await readParquetFile(fileBlob, schema);
        // console.log(`Successfully loaded ${fileName} from public folder`);
      } else {
        // Handle drag-and-drop files directly
        data = await readParquetFile(file, schema);
        // console.log(`Successfully loaded ${file.name} from drag-and-drop`);
      }

      if (schema === "entity") {
        entitiesArray.push(data);
      } else if (schema === "relationship") {
        relationshipsArray.push(data);
      } else if (schema === "document") {
        documentsArray.push(data);
      } else if (schema === "text_unit") {
        textUnitsArray.push(data);
      } else if (schema === "community") {
        communitiesArray.push(data);
      } else if (schema === "community_report") {
        communityReportsArray.push(data);
      } else if (schema === "covariate") {
        covariatesArray.push(data);
      } else if (schema === "claim_cluster") {
        claimClustersArray.push(data);
      } else if (schema === "claim_pair_audit") {
        claimPairAuditArray.push(data);
      }
    }

    setEntities(sanitizeEntities(entitiesArray.flat()));
    setRelationships(relationshipsArray.flat());
    setDocuments(documentsArray.flat());
    setTextUnits(textUnitsArray.flat());
    setCommunities(communitiesArray.flat());
    setCommunityReports(communityReportsArray.flat());
    setCovariates(covariatesArray.flat());
    setClaimClusters(claimClustersArray.flat());
    setClaimPairAudit(claimPairAuditArray.flat());
  };

  const checkFileExists = async (filePath: string) => {
    try {
      const response = await fetch(filePath, {
        method: "HEAD",
        cache: "no-store",
      });

      if (!response.ok) {
        console.warn(
          `File does not exist: ${filePath} (status: ${response.status})`
        );
        return false;
      }

      // Local static servers (e.g. `serve`) often omit Content-Type for .parquet,
      // or use types other than application/octet-stream. Accept any successful HEAD.
      const contentType = (response.headers.get("Content-Type") || "").toLowerCase();
      const looksLikeHtml =
        contentType.includes("text/html") || contentType.includes("application/json");
      if (looksLikeHtml) {
        return false;
      }

      console.log(`File exists: ${filePath}`);
      return true;
    } catch (error) {
      console.error(`Error checking file existence for ${filePath}`, error);
      return false;
    }
  };

  const loadArtifactsFromDir = async (
    artifactDir: string,
    options?: { navigateTo?: string | false }
  ) => {
    const filesToLoad: string[] = [];

    for (const baseName of [
      ...baseFileNames,
      "claim_clusters.parquet",
      "claim_pair_audit.parquet",
    ]) {
      const prefixedPath = `${artifactDir}/create_final_${baseName}`;
      const unprefixedPath = `${artifactDir}/${baseName}`;

      if (await checkFileExists(prefixedPath)) {
        filesToLoad.push(prefixedPath);
      } else if (await checkFileExists(unprefixedPath)) {
        filesToLoad.push(unprefixedPath);
      }
    }

    if (filesToLoad.length === 0) {
      return false;
    }

    console.log(`Loading artifacts from ${artifactDir}`);
    await loadFiles(filesToLoad);
    if (options?.navigateTo !== false) {
      navigate(options?.navigateTo ?? "/graph", { replace: true });
    }
    return true;
  };

  const loadDefaultFiles = async (preferredDataset?: string) => {
    const dataset = preferredDataset ?? DEFAULT_ARTIFACT_DATASET;
    const datasetOrder = [
      dataset,
      DEFAULT_ARTIFACT_DATASET,
      "real_qwen36",
      "new_fake_news_36",
      "default",
    ];
    const seen = new Set<string>();

    for (const name of datasetOrder) {
      if (seen.has(name)) continue;
      seen.add(name);
      const loaded = await loadArtifactsFromDir(datasetDir(name));
      if (loaded) {
        return name;
      }
    }

    console.log("No default files found in public/artifacts.");
    return null;
  };

  return {
    entities,
    relationships,
    documents,
    textunits,
    communities,
    covariates,
    claimClusters,
    claimPairAudit,
    communityReports,
    handleFilesRead,
    loadDefaultFiles,
    loadArtifactsFromDir,
  };
};

export default useFileHandler;
