import React from "react";
import { Box, Button, Typography } from "@mui/material";
import { useNavigate } from "react-router-dom";
import {
  ClaimView,
  claimGraphPath,
  claimViewFromPath,
} from "../utils/claim-routes";

interface ClaimViewSwitcherProps {
  pathname: string;
  nodeCount?: number;
}

const ClaimViewSwitcher: React.FC<ClaimViewSwitcherProps> = ({
  pathname,
  nodeCount,
}) => {
  const navigate = useNavigate();
  const activeView = claimViewFromPath(pathname);

  if (!activeView) {
    return null;
  }

  const views: { id: ClaimView; label: string; hint: string }[] = [
    {
      id: "original",
      label: "Original",
      hint: "One node per extracted claim",
    },
    {
      id: "merged",
      label: "Merged",
      hint: "FAISS-deduplicated claims",
    },
  ];

  return (
    <Box
      sx={{
        display: "flex",
        flexWrap: "wrap",
        alignItems: "center",
        gap: 1,
        mb: 1,
      }}
    >
      <Typography variant="body2" color="text.secondary" sx={{ mr: 0.5 }}>
        Claim graph:
      </Typography>
      {views.map((view) => (
        <Button
          key={view.id}
          size="small"
          variant={activeView === view.id ? "contained" : "outlined"}
          onClick={() => navigate(claimGraphPath(view.id))}
          title={view.hint}
        >
          {view.label}
          {activeView === view.id && nodeCount !== undefined
            ? ` (${nodeCount})`
            : ""}
        </Button>
      ))}
    </Box>
  );
};

export default ClaimViewSwitcher;
