import React, { useState, useCallback, useRef, useEffect, useMemo } from "react";
import ForceGraph2D from "react-force-graph-2d";
import ForceGraph3D from "react-force-graph-3d";
import {
  CustomGraphData,
  CustomLink,
  CustomNode,
} from "../models/custom-graph-data";
import {
  Box,
  Button,
  Checkbox,
  FormControlLabel,
  FormGroup,
  IconButton,
  Slider,
  Switch,
  Tooltip,
  Typography,
  useTheme,
} from "@mui/material";
import FullscreenIcon from "@mui/icons-material/Fullscreen";
import FullscreenExitIcon from "@mui/icons-material/FullscreenExit";
import SearchIcon from "@mui/icons-material/Search";
import DeleteIcon from "@mui/icons-material/Delete";
import Fuse from "fuse.js";
import {
  CSS2DRenderer,
  CSS2DObject,
} from "three/examples/jsm/renderers/CSS2DRenderer";
import * as THREE from "three";
import { Renderer } from "three";
import SearchDrawer from "./SearchDrawer";
import DetailDrawer from "./DetailDrawer";
import { SearchResult } from "../models/search-result";
import agent from "../api/agent";
import APISearchDrawer from "./APISearchDrawer";
import SpriteText from "three-spritetext";
import {
  ENTITY_DISPLAY_COLORS,
  getEntityNodeColor,
  getGeneralTypeColor,
  isCovid19Entity,
  isDisplayEntityType,
} from "../utils/entity-type-colors";
import { isMergedClaimNode } from "../utils/claim-merge-utils";
import { forceCollide, forceManyBody, forceX, forceY } from "d3-force-3d";

type Coords = {
  x: number;
  y: number;
  z: number;
};

interface GraphViewerProps {
  data: CustomGraphData;
  graphType: "2d" | "3d";
  isFullscreen: boolean;
  onToggleFullscreen: () => void;
  onToggleGraphType: (event: React.ChangeEvent<HTMLInputElement>) => void;
  includeDocuments: boolean;
  onIncludeDocumentsChange: React.Dispatch<React.SetStateAction<boolean>>;
  includeTextUnits: boolean;
  onIncludeTextUnitsChange: React.Dispatch<React.SetStateAction<boolean>>;
  includeCommunities: boolean;
  onIncludeCommunitiesChange: React.Dispatch<React.SetStateAction<boolean>>;
  includeCovariates: boolean;
  onIncludeCovariatesChange: React.Dispatch<React.SetStateAction<boolean>>;
  hasDocuments: boolean;
  hasTextUnits: boolean;
  hasCommunities: boolean;
  hasCovariates: boolean;
  minConnections: number;
  onMinConnectionsChange: React.Dispatch<React.SetStateAction<number>>;
  totalEntities: number;
}

const NODE_R = 18;
const DEFAULT_LINK_DISTANCE = 55;
const DEFAULT_CHARGE_STRENGTH = -90;
const ENTITY_LINK_DISTANCE = 58;
const ENTITY_CHARGE_STRENGTH = -80;
const ENTITY_LINK_STRENGTH = 0.95;
const ENTITY_NODE_COLLISION_RADIUS = NODE_R + 4;
const ENTITY_LABEL_COLLISION_RADIUS = NODE_R + 14;
// Claim-as-node graph: tight SAME_ARTICLE cliques; cap repulsion range so separate
// article clusters are not pushed to opposite sides of the canvas.
const CLAIM_LINK_DISTANCE = 26;
const CLAIM_CHARGE_STRENGTH = -16;
const CLAIM_CHARGE_DISTANCE_MAX = 85;
const CLAIM_LINK_STRENGTH = 1.1;
const CLAIM_CENTER_STRENGTH = 0.06;
const CLAIM_NODE_COLLISION_RADIUS = NODE_R + 12;
const CLAIM_LABEL_COLLISION_RADIUS = NODE_R + 24;
const CLAIM_LABEL_FONT_SIZE = 6;
const MERGED_CLAIM_COLOR = "#000000";
const CLAIM_TYPE_PALETTE = [
  "#4e79a7",
  "#f28e2b",
  "#e15759",
  "#76b7b2",
  "#59a14f",
  "#edc948",
  "#b07aa1",
  "#ff9da7",
  "#9c755f",
  "#bab0ac",
];

const GraphViewer: React.FC<GraphViewerProps> = ({
  data,
  graphType,
  isFullscreen,
  includeDocuments,
  onIncludeDocumentsChange,
  includeTextUnits,
  onIncludeTextUnitsChange,
  includeCommunities,
  onIncludeCommunitiesChange,
  includeCovariates,
  onIncludeCovariatesChange,
  onToggleFullscreen,
  onToggleGraphType,
  hasDocuments,
  hasTextUnits,
  hasCommunities,
  hasCovariates,
  minConnections,
  onMinConnectionsChange,
  totalEntities,
}) => {
  const theme = useTheme();
  const [highlightNodes, setHighlightNodes] = useState<Set<CustomNode>>(
    new Set()
  );
  const [highlightLinks, setHighlightLinks] = useState<Set<CustomLink>>(
    new Set()
  );
  const [hoverNode, setHoverNode] = useState<CustomNode | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState<
    (CustomNode | CustomLink)[]
  >([]);
  const [rightDrawerOpen, setRightDrawerOpen] = useState(false);
  const [bottomDrawerOpen, setBottomDrawerOpen] = useState(false);
  const [selectedNode, setSelectedNode] = useState<CustomNode | null>(null);
  const [selectedRelationship, setSelectedRelationship] =
    useState<CustomLink | null>(null);
  const [linkedNodes, setLinkedNodes] = useState<CustomNode[]>([]);
  const [linkedRelationships, setLinkedRelationships] = useState<CustomLink[]>(
    []
  );
  const [showLabels, setShowLabels] = useState(false);
  const [showLinkLabels, setShowLinkLabels] = useState(false);
  const [showHighlight, setShowHighlight] = useState(true);
  const claimLabelsInitialized = useRef(false);
  const graphRef = useRef<any>();
  const extraRenderers = [new CSS2DRenderer() as any as Renderer];
  const nodeCount = data.nodes.length;
  const linkCount = data.links.length;

  const [apiDrawerOpen, setApiDrawerOpen] = useState(false);
  const [apiSearchResults, setApiSearchResults] = useState<SearchResult | null>(
    null
  );
  const [serverUp, setServerUp] = useState<boolean>(false);

  const [graphData, setGraphData] = useState<CustomGraphData>(data);

  const initialGraphData = useRef<CustomGraphData>(data);

  useEffect(() => {
    setGraphData(data);
    initialGraphData.current = data;
  }, [data]);

  useEffect(() => {
    checkServerStatus();
  }, []);

  const toggleApiDrawer = (open: boolean) => () => {
    setApiDrawerOpen(open);
  };

  const handleApiSearch = async (
    query: string,
    searchType: "local" | "global"
  ) => {
    try {
      const data: SearchResult =
        searchType === "local"
          ? await agent.Search.local(query)
          : await agent.Search.global(query);

      setApiSearchResults(data);
      // Process the search result to update the graph data
      updateGraphData(data.context_data);
    } catch (err) {
      console.error("An error occurred during the API search.", err);
    } finally {
    }
  };

  const checkServerStatus = async () => {
    try {
      const response = await agent.Status.check();
      if (response.status === "Server is up and running") {
        setServerUp(true);
      } else {
        setServerUp(false);
      }
    } catch (error) {
      setServerUp(false);
    }
  };

  const updateGraphData = (contextData: any) => {
    if (!contextData) return;

    const newNodes: CustomNode[] = [];
    const newLinks: CustomLink[] = [];

    const baseGraphData = initialGraphData.current;

    // Assuming contextData has keys like entities, reports, relationships, sources
    Object.entries(contextData).forEach(([key, items]) => {
      if (Array.isArray(items)) {
        items.forEach((item) => {
          if (key === "relationships") {
            // Handle links
            const existingLink = baseGraphData.links.find(
              (link) =>
                link.human_readable_id?.toString() === item.id.toString()
            );

            if (existingLink) {
              newLinks.push(existingLink);
            }
          } else if (key === "entities") {
            const existingNode = baseGraphData.nodes.find(
              (node) =>
                node.human_readable_id?.toString() === item.id.toString() &&
                !node.covariate_type
            );
            if (existingNode) {
              newNodes.push(existingNode);
            }
          } else if (key === "reports") {
            const existingNode = baseGraphData.nodes.find(
              (node) => node.uuid === item.id.toString()
            );
            if (existingNode) {
              newNodes.push(existingNode);
            }
          } else if (key === "sources") {
            const existingNode = baseGraphData.nodes.find(
              (node) => node.text?.toString() === item.text
            );
            if (existingNode) {
              newNodes.push(existingNode);
            }
          } else if (key === "covariates" || key === "claims") {
            const existingNode = baseGraphData.nodes.find(
              (node) =>
                node.human_readable_id?.toString() === item.id.toString() &&
                node.covariate_type
            );
            if (existingNode) {
              newNodes.push(existingNode);
            }
          }
        });
      }
    });

    // Update the graph data with the new nodes and links
    const updatedGraphData: CustomGraphData = {
      nodes: [...newNodes],
      links: [...newLinks],
    };

    // Set the updated data to trigger re-render
    setGraphData(updatedGraphData);
  };

  const fuse = new Fuse([...data.nodes, ...data.links], {
    keys: [
      "uuid",
      "id",
      "name",
      "type",
      "description",
      "source",
      "target",
      "title",
      "summary",
    ],
    threshold: 0.3,
  });

  const handleNodeHover = useCallback((node: CustomNode | null) => {
    const newHighlightNodes = new Set<CustomNode>();
    const newHighlightLinks = new Set<CustomLink>();

    if (node) {
      newHighlightNodes.add(node);
      node.neighbors?.forEach((neighbor) => newHighlightNodes.add(neighbor));
      node.links?.forEach((link) => newHighlightLinks.add(link));
    }

    setHighlightNodes(newHighlightNodes);
    setHighlightLinks(newHighlightLinks);
    setHoverNode(node);
  }, []);

  const handleLinkHover = useCallback((link: CustomLink | null) => {
    const newHighlightNodes = new Set<CustomNode>();
    const newHighlightLinks = new Set<CustomLink>();

    if (link) {
      newHighlightLinks.add(link);
      if (typeof link.source !== "string") newHighlightNodes.add(link.source);
      if (typeof link.target !== "string") newHighlightNodes.add(link.target);
    }

    setHighlightNodes(newHighlightNodes);
    setHighlightLinks(newHighlightLinks);
  }, []);

  const usesDisplayEntityColors = graphData.nodes.some((node) =>
    isDisplayEntityType(node.type)
  );
  const usesClaimLayout = graphData.links.some(
    (link) => link.type === "SAME_ARTICLE"
  );
  // Fake/real entity graphs use raw Romanian types, so they won't match
  // display-entity labels — still treat them as entity graphs for styling.
  const usesEntityLayout = !usesClaimLayout;

  const claimTypeColors = useMemo(() => {
    const map = new Map<string, string>();
    if (!usesClaimLayout) return map;
    const types = [...new Set(graphData.nodes.map((node) => node.type || ""))].sort();
    types.forEach((type, index) => {
      map.set(type, CLAIM_TYPE_PALETTE[index % CLAIM_TYPE_PALETTE.length]);
    });
    return map;
  }, [graphData.nodes, usesClaimLayout]);

  const getClaimNodeColor = useCallback(
    (node: CustomNode) => {
      if (isMergedClaimNode(node)) {
        return MERGED_CLAIM_COLOR;
      }
      return claimTypeColors.get(node.type || "") || "#888888";
    },
    [claimTypeColors]
  );

  const getGraphNodeColorProps = () => {
    if (usesDisplayEntityColors) {
      return { nodeColor: (node: object) => getEntityNodeColor(node as CustomNode) };
    }
    if (usesClaimLayout) {
      return { nodeColor: (node: object) => getClaimNodeColor(node as CustomNode) };
    }
    return {
      nodeColor: (node: object) => getGeneralTypeColor((node as CustomNode).type),
    };
  };

  useEffect(() => {
    if (usesClaimLayout && !claimLabelsInitialized.current) {
      setShowLabels(true);
      claimLabelsInitialized.current = true;
    }
  }, [usesClaimLayout]);

  useEffect(() => {
    const graph = graphRef.current;
    if (!graph?.d3Force) return;

    if (usesEntityLayout) {
      graph.d3Force("x", null);
      graph.d3Force("y", null);
      graph.d3Force("charge")?.strength(ENTITY_CHARGE_STRENGTH);
      graph
        .d3Force("link")
        ?.distance(ENTITY_LINK_DISTANCE)
        .strength(ENTITY_LINK_STRENGTH);

      const collisionRadius = showLabels
        ? ENTITY_LABEL_COLLISION_RADIUS
        : ENTITY_NODE_COLLISION_RADIUS;
      graph.d3Force(
        "collision",
        forceCollide<CustomNode>().radius(collisionRadius)
      );
    } else if (usesClaimLayout) {
      graph.d3Force(
        "charge",
        forceManyBody()
          .strength(CLAIM_CHARGE_STRENGTH)
          .distanceMax(CLAIM_CHARGE_DISTANCE_MAX)
      );
      graph
        .d3Force("link")
        ?.distance(CLAIM_LINK_DISTANCE)
        .strength(CLAIM_LINK_STRENGTH);
      graph.d3Force("x", forceX(0).strength(CLAIM_CENTER_STRENGTH));
      graph.d3Force("y", forceY(0).strength(CLAIM_CENTER_STRENGTH));

      const collisionRadius = showLabels
        ? CLAIM_LABEL_COLLISION_RADIUS
        : CLAIM_NODE_COLLISION_RADIUS;
      graph.d3Force(
        "collision",
        forceCollide<CustomNode>().radius(collisionRadius)
      );
    } else {
      graph.d3Force("x", null);
      graph.d3Force("y", null);
      graph.d3Force("charge")?.strength(DEFAULT_CHARGE_STRENGTH);
      graph.d3Force("link")?.distance(DEFAULT_LINK_DISTANCE);
      graph.d3Force("collision", null);
    }

    graph.d3ReheatSimulation?.();
  }, [graphData, usesEntityLayout, usesClaimLayout, showLabels]);

  const paintRing = useCallback(
    (node: CustomNode, ctx: CanvasRenderingContext2D) => {
      ctx.beginPath();
      ctx.arc(node.x!, node.y!, NODE_R * 1.4, 0, 2 * Math.PI, false);
      if (highlightNodes.has(node)) {
        ctx.fillStyle = node === hoverNode ? "red" : "orange";
        ctx.globalAlpha = 1; // full opacity
      } else {
        ctx.fillStyle = "gray";
        ctx.globalAlpha = 0.3; // reduced opacity for non-highlighted nodes
      }
      ctx.fill();
      ctx.globalAlpha = 1; // reset alpha for other drawings
    },
    [hoverNode, highlightNodes]
  );

  const paintCovid19Border = useCallback(
    (node: CustomNode, ctx: CanvasRenderingContext2D) => {
      if (!isCovid19Entity(node) || node.x === undefined || node.y === undefined) {
        return;
      }
      ctx.beginPath();
      ctx.arc(node.x, node.y, NODE_R * 1.55, 0, 2 * Math.PI, false);
      ctx.strokeStyle = "#000000";
      ctx.lineWidth = 2.5;
      ctx.stroke();
    },
    []
  );

  const paintMergedClaimIndicator = useCallback(
    (node: CustomNode, ctx: CanvasRenderingContext2D) => {
      if (
        !isMergedClaimNode(node) ||
        node.x === undefined ||
        node.y === undefined
      ) {
        return;
      }
      const size = node.merge_cluster_size ?? 2;
      const radius = NODE_R * (1.2 + Math.min(size - 1, 3) * 0.15);

      ctx.beginPath();
      ctx.arc(node.x, node.y, radius, 0, 2 * Math.PI, false);
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 2;
      ctx.stroke();

      const badge = `×${size}`;
      ctx.font = "bold 6px Sans-Serif";
      const badgeWidth = ctx.measureText(badge).width + 4;
      const badgeX = node.x + radius * 0.55;
      const badgeY = node.y - radius * 0.85;
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(badgeX - badgeWidth / 2, badgeY - 5, badgeWidth, 8);
      ctx.fillStyle = "#000000";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(badge, badgeX, badgeY - 1);
    },
    []
  );

  const getClaimNodeVal = useCallback((node: CustomNode) => {
    const size = node.merge_cluster_size ?? 1;
    return size > 1 ? size : 1;
  }, []);

  const handleSearch = () => {
    const results = fuse.search(searchTerm).map((result) => result.item);
    const nodeResults = results.filter((item) => "neighbors" in item);
    const linkResults = results.filter(
      (item) => "source" in item && "target" in item
    );
    setSearchResults([...nodeResults, ...linkResults]);
    setRightDrawerOpen(true);
  };

  const toggleDrawer = (open: boolean) => () => {
    setRightDrawerOpen(open);
  };

  const handleFocusButtonClick = (node: CustomNode) => {
    const newHighlightNodes = new Set<CustomNode>();
    newHighlightNodes.add(node);
    node.neighbors?.forEach((neighbor) => newHighlightNodes.add(neighbor));
    node.links?.forEach((link) => highlightLinks.add(link));

    setHighlightNodes(newHighlightNodes);
    setHoverNode(node);

    if (graphRef.current) {
      if (graphType === "2d") {
        graphRef.current.centerAt(node.x, node.y, 1000);
        graphRef.current.zoom(8, 1000);
      } else {
        graphRef.current.cameraPosition(
          { x: node.x, y: node.y, z: 300 }, // new position
          { x: node.x, y: node.y, z: 0 }, // lookAt
          3000 // ms transition duration
        );
      }
    }

    // Simulate mouse hover on the focused node
    setTimeout(() => {
      handleNodeHover(node);
    }, 1000); // Adjust delay as needed

    setRightDrawerOpen(false);
  };

  const handleFocusLinkClick = (link: CustomLink) => {
    const newHighlightNodes = new Set<CustomNode>();
    const newHighlightLinks = new Set<CustomLink>();

    newHighlightLinks.add(link);
    let sourceNode: CustomNode | undefined;
    let targetNode: CustomNode | undefined;

    if (typeof link.source !== "string") {
      newHighlightNodes.add(link.source);
      sourceNode = link.source;
    }

    if (typeof link.target !== "string") {
      newHighlightNodes.add(link.target);
      targetNode = link.target;
    }

    setHighlightNodes(newHighlightNodes);
    setHighlightLinks(newHighlightLinks);

    if (
      graphRef.current &&
      sourceNode &&
      targetNode &&
      sourceNode.x &&
      targetNode.x &&
      sourceNode.y &&
      targetNode.y
    ) {
      const midX = (sourceNode.x + targetNode.x) / 2;
      const midY = (sourceNode.y + targetNode.y) / 2;

      if (graphType === "2d") {
        graphRef.current.centerAt(midX, midY, 1000);
        graphRef.current.zoom(8, 1000);
      } else {
        graphRef.current.cameraPosition(
          { x: midX, y: midY, z: 300 }, // new position
          { x: midX, y: midY, z: 0 }, // lookAt
          3000 // ms transition duration
        );
      }
    }

    // Simulate mouse hover on the focused link
    setTimeout(() => {
      handleLinkHover(link);
    }, 1000); // Adjust delay as needed

    setRightDrawerOpen(false);
  };

  const handleNodeClick = (node: CustomNode) => {
    setSelectedRelationship(null);
    setSelectedNode(node);
    setLinkedNodes(node.neighbors || []);
    setLinkedRelationships(node.links || []);
    setBottomDrawerOpen(true);
  };

  const handleLinkClick = (link: CustomLink) => {
    setSelectedNode(null);
    setSelectedRelationship(link);
    const linkSource =
      typeof link.source === "object"
        ? (link.source as CustomNode).id
        : link.source;
    const linkTarget =
      typeof link.target === "object"
        ? (link.target as CustomNode).id
        : link.target;
    const sourceNode = data.nodes.find((node) => node.id === linkSource);
    const targetNode = data.nodes.find((node) => node.id === linkTarget);
    if (sourceNode && targetNode) {
      const linkedNodes = [sourceNode, targetNode];
      setLinkedNodes(linkedNodes);
      const linkedRelationships = [link];
      setLinkedRelationships(linkedRelationships);
      setBottomDrawerOpen(true);
    }
  };

  const getBackgroundColor = () =>
    theme.palette.mode === "dark" ? "#000000" : "#FFFFFF";

  // Only semantic claim-relation types are directed; entity graphs (RELATED, etc.)
  // stay undirected like the original GraphRAG visualization.
  const DIRECTED_RELATIONS = new Set([
    "ENTAILS",
    "SPECIFIC_GENERAL",
    "CAUSES",
    "TEMPORAL",
  ]);

  const RELATION_COLORS: { [key: string]: string } = {
    ENTAILS: "#4caf50",
    SPECIFIC_GENERAL: "#2196f3",
    CAUSES: "#ff9800",
    TEMPORAL: "#9c27b0",
    PARAPHRASE: "#00bcd4",
    CONTRADICTS: "#f44336",
  };

  const getLinkWidth = (link: CustomLink) =>
    usesEntityLayout
      ? 0.35
      : Math.min(0.35 + (link.weight ?? 1) * 0.22, 2.1);

  const getHighlightLinkWidth = (link: CustomLink) =>
    showHighlight && highlightLinks.has(link)
      ? usesEntityLayout
        ? 1.4
        : 2.5
      : getLinkWidth(link);

  const isDirectedRelation = (link: CustomLink) =>
    !usesEntityLayout &&
    !!link.type &&
    DIRECTED_RELATIONS.has(link.type);

  const getRelationColor = (link: CustomLink, fallback: string) =>
    (link.type && RELATION_COLORS[link.type]) || fallback;

  const getLinkColor = (link: CustomLink) => {
    if (usesEntityLayout) {
      const alpha = showHighlight && highlightLinks.has(link) ? 0.7 : 0.32;
      return theme.palette.mode === "dark"
        ? `rgba(200, 200, 200, ${alpha})`
        : `rgba(90, 90, 90, ${alpha})`;
    }
    return getRelationColor(
      link,
      theme.palette.mode === "dark" ? "gray" : "lightgray"
    );
  };

  const get3DLinkColor = (link: CustomLink) =>
    usesEntityLayout
      ? getLinkColor(link)
      : getRelationColor(
          link,
          theme.palette.mode === "dark" ? "lightgray" : "gray"
        );

  const getlinkDirectionalParticleColor = (link: CustomLink) =>
    getRelationColor(link, theme.palette.mode === "dark" ? "lightgray" : "gray");

  const getLinkArrowLength = (link: CustomLink) =>
    isDirectedRelation(link) ? 4 : 0;

  const getLinkParticles = (link: CustomLink) => {
    if (!showHighlight || usesEntityLayout) return 0;
    return highlightLinks.has(link) ? 4 : 0;
  };

  const LABEL_TEXT_COLOR = "#000000";
  const LABEL_BG_COLOR = "rgba(255, 255, 255, 0.92)";

  const renderNodeLabel = (node: CustomNode, ctx: CanvasRenderingContext2D) => {
    if (!showLabels) return; // Only render the label if showLabels is true

    const label = node.name || "";
    const fontSize = usesClaimLayout ? CLAIM_LABEL_FONT_SIZE : 6;
    const padding = usesClaimLayout ? 3 : 2;
    const bold = isCovid19Entity(node);
    const fontWeight = bold ? 700 : usesEntityLayout ? 600 : 400;
    ctx.font = `${fontWeight} ${fontSize}px Sans-Serif`;

    // Calculate label dimensions
    const textWidth = ctx.measureText(label).width;
    const boxWidth = textWidth + padding * 2;
    const boxHeight = fontSize + padding * 2;
    const labelOffsetY = usesClaimLayout ? NODE_R + boxHeight / 2 + 4 : 0;

    if (node.x && node.y) {
      const labelX = node.x;
      const labelY = node.y + labelOffsetY;
      // Draw the background rectangle with rounded corners
      ctx.fillStyle = LABEL_BG_COLOR;
      ctx.beginPath();
      ctx.moveTo(labelX - boxWidth / 2 + 5, labelY - boxHeight / 2);
      ctx.lineTo(labelX + boxWidth / 2 - 5, labelY - boxHeight / 2);
      ctx.quadraticCurveTo(
        labelX + boxWidth / 2,
        labelY - boxHeight / 2,
        labelX + boxWidth / 2,
        labelY - boxHeight / 2 + 5
      );
      ctx.lineTo(labelX + boxWidth / 2, labelY + boxHeight / 2 - 5);
      ctx.quadraticCurveTo(
        labelX + boxWidth / 2,
        labelY + boxHeight / 2,
        labelX + boxWidth / 2 - 5,
        labelY + boxHeight / 2
      );
      ctx.lineTo(labelX - boxWidth / 2 + 5, labelY + boxHeight / 2);
      ctx.quadraticCurveTo(
        labelX - boxWidth / 2,
        labelY + boxHeight / 2,
        labelX - boxWidth / 2,
        labelY + boxHeight / 2 - 5
      );
      ctx.lineTo(labelX - boxWidth / 2, labelY - boxHeight / 2 + 5);
      ctx.quadraticCurveTo(
        labelX - boxWidth / 2,
        labelY - boxHeight / 2,
        labelX - boxWidth / 2 + 5,
        labelY - boxHeight / 2
      );
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = LABEL_TEXT_COLOR;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(label, labelX, labelY);
    }
  };

  const nodeThreeObject = (node: CustomNode) => {
    if (!showLabels) {
      return new THREE.Object3D();
    }

    try {
      const nodeEl = document.createElement("div");
      nodeEl.textContent = node.name || node.id; // Use either name or id for the label
      nodeEl.style.color = LABEL_TEXT_COLOR;
      nodeEl.style.backgroundColor = LABEL_BG_COLOR;
      nodeEl.style.padding = "2px 4px";
      nodeEl.style.borderRadius = "4px";
      nodeEl.style.fontSize = usesEntityLayout ? "12px" : "10px";
      nodeEl.style.fontWeight = isCovid19Entity(node)
        ? "700"
        : usesEntityLayout
          ? "600"
          : "400";
      if (isCovid19Entity(node)) {
        nodeEl.style.border = "2.5px solid #000000";
      }
      nodeEl.className = "node-label";

      return new CSS2DObject(nodeEl);
    } catch (error) {
      console.error("Error creating 3D object:", error);
      return new THREE.Object3D(); // Fallback in case of error
    }
  };

  const localSearchEnabled = hasCovariates
    ? includeTextUnits && includeCommunities && includeCovariates
    : includeTextUnits && includeCommunities;

  const clearSearchResults = () => {
    setGraphData(initialGraphData.current);
    setApiSearchResults(null);
  };

  return (
    <Box
      sx={{
        height: isFullscreen ? "100vh" : "calc(100vh - 64px)",
        width: isFullscreen ? "100vw" : "100%",
        position: isFullscreen ? "fixed" : "relative",
        top: 0,
        left: 0,
        zIndex: isFullscreen ? 1300 : "auto",
        overflow: "hidden",
        margin: 0,
        padding: 0,
        backgroundColor: getBackgroundColor(),
      }}
    >
      <Box
        sx={{
          position: "absolute",
          top: 10,
          right: 10,
          zIndex: 1400,
          display: "flex",
          flexDirection: "column",
          gap: 2,
          alignItems: "flex-end",
        }}
      >
        <Box sx={{ display: "flex", gap: 2, alignItems: "center" }}>
          <Button
            variant="contained"
            onClick={toggleDrawer(true)}
            startIcon={<SearchIcon />}
          >
            Search Nodes/Links
          </Button>
          {/* <FormControlLabel
            control={
              <Switch
                checked={graphType === "3d"}
                onChange={onToggleGraphType}
              />
            }
            label="3D View"
          /> */}
          {/* <FormControlLabel
            control={
              <Switch
                checked={showLabels}
                onChange={() => setShowLabels(!showLabels)}
              />
            }
            label="Show Node Labels"
          />
          <FormControlLabel
            control={
              <Switch
                checked={showLinkLabels}
                onChange={() => setShowLinkLabels(!showLinkLabels)}
              />
            }
            label="Show Relationship Labels"
          />
          <FormControlLabel
            control={
              <Switch
                checked={showHighlight}
                onChange={() => setShowHighlight(!showHighlight)}
              />
            }
            label="Show Highlight"
          /> */}
          <Tooltip title={isFullscreen ? "Exit Full Screen" : "Full Screen"}>
            <IconButton onClick={onToggleFullscreen} color="inherit">
              {isFullscreen ? <FullscreenExitIcon /> : <FullscreenIcon />}
            </IconButton>
          </Tooltip>
        </Box>

        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            gap: 1,
            alignItems: "flex-start",
          }}
        >
          <FormControlLabel
            control={
              <Switch
                checked={graphType === "3d"}
                onChange={onToggleGraphType}
              />
            }
            label="3D View"
          />
          <FormControlLabel
            control={
              <Switch
                checked={showLabels}
                onChange={() => setShowLabels(!showLabels)}
              />
            }
            label="Show Node Labels"
          />
          <FormControlLabel
            control={
              <Switch
                checked={showLinkLabels}
                onChange={() => setShowLinkLabels(!showLinkLabels)}
              />
            }
            label="Show Link Labels"
          />
          <FormControlLabel
            control={
              <Switch
                checked={showHighlight}
                onChange={() => setShowHighlight(!showHighlight)}
              />
            }
            label="Show Highlight"
          />
        </Box>

        <FormGroup>
          <FormControlLabel
            control={
              <Checkbox
                checked={includeDocuments}
                onChange={() => onIncludeDocumentsChange(!includeDocuments)}
                disabled={!hasDocuments || apiSearchResults !== null}
              />
            }
            label="Include Documents"
          />
          <FormControlLabel
            control={
              <Checkbox
                checked={includeTextUnits}
                // onChange={() => onIncludeTextUnitsChange(!includeTextUnits)}
                onChange={() => {
                  if (!includeTextUnits) {
                    onIncludeTextUnitsChange(true);
                  } else if (includeTextUnits && !includeCovariates) {
                    onIncludeTextUnitsChange(false);
                  } else {
                    onIncludeTextUnitsChange(false);
                    onIncludeCovariatesChange(false); // Uncheck Covariates when Text Units is unchecked
                  }
                }}
                disabled={!hasTextUnits || apiSearchResults !== null}
              />
            }
            label="Include Text Units"
          />
          <FormControlLabel
            control={
              <Checkbox
                checked={includeCommunities}
                onChange={() => onIncludeCommunitiesChange(!includeCommunities)}
                disabled={!hasCommunities || apiSearchResults !== null}
              />
            }
            label="Include Communities"
          />

          <FormControlLabel
            control={
              <Checkbox
                checked={includeCovariates}
                onChange={() => {
                  if (!includeCovariates) {
                    if (!includeTextUnits) {
                      onIncludeTextUnitsChange(true);
                    }
                    onIncludeCovariatesChange(true);
                  } else {
                    onIncludeCovariatesChange(false);
                  }
                }}
                disabled={!hasCovariates || apiSearchResults !== null}
              />
            }
            label="Include Covariates"
          />
        </FormGroup>

        {totalEntities > 0 && (
          <Box sx={{ width: 200, mt: 2 }}>
            <Typography variant="body2" gutterBottom>
              Min Connections: {minConnections === 0 ? "None" : minConnections}
              {` · ${graphData.nodes.length} nodes`}
            </Typography>
            <Slider
              value={minConnections}
              onChange={(_, value) => onMinConnectionsChange(value as number)}
              min={0}
              max={50}
              step={1}
              marks={[
                { value: 0, label: "0" },
                { value: 15, label: "15" },
              ]}
              valueLabelDisplay="auto"
              valueLabelFormat={(value) => (value === 0 ? "None" : value)}
              disabled={apiSearchResults !== null}
            />
          </Box>
        )}
      </Box>

      <APISearchDrawer
        apiDrawerOpen={apiDrawerOpen}
        toggleDrawer={toggleApiDrawer}
        handleApiSearch={handleApiSearch}
        apiSearchResults={apiSearchResults}
        localSearchEnabled={localSearchEnabled}
        globalSearchEnabled={includeCommunities}
        hasCovariates={hasCovariates}
        serverUp={serverUp}
      />

      <SearchDrawer
        searchTerm={searchTerm}
        setSearchTerm={setSearchTerm}
        handleSearch={handleSearch}
        searchResults={searchResults}
        rightDrawerOpen={rightDrawerOpen}
        toggleDrawer={toggleDrawer}
        handleFocusButtonClick={handleFocusButtonClick}
        handleNodeClick={handleNodeClick}
        handleFocusLinkClick={handleFocusLinkClick}
        handleLinkClick={handleLinkClick}
      />

      <DetailDrawer
        bottomDrawerOpen={bottomDrawerOpen}
        setBottomDrawerOpen={setBottomDrawerOpen}
        selectedNode={selectedNode}
        selectedRelationship={selectedRelationship}
        linkedNodes={linkedNodes}
        linkedRelationships={linkedRelationships}
      />

      {graphType === "2d" ? (
        <ForceGraph2D
          ref={graphRef}
          graphData={graphData}
          {...getGraphNodeColorProps()}
          {...(usesClaimLayout
            ? {
                warmupTicks: 120,
                cooldownTicks: 200,
                d3AlphaDecay: 0.018,
                nodeVal: (node) => getClaimNodeVal(node as CustomNode),
              }
            : {})}
          nodeRelSize={NODE_R}
          autoPauseRedraw={false}
          linkWidth={getHighlightLinkWidth}
          linkDirectionalParticles={getLinkParticles}
          linkDirectionalParticleWidth={(link) =>
            getLinkParticles(link as CustomLink) > 0 ? 4 : 0
          }
          linkDirectionalParticleColor={
            showHighlight ? getlinkDirectionalParticleColor : undefined
          }
          linkDirectionalArrowLength={getLinkArrowLength}
          linkDirectionalArrowRelPos={1}
          linkDirectionalArrowColor={getLinkColor}
          nodeCanvasObjectMode={(node) => {
            const customNode = node as CustomNode;
            if (showHighlight && highlightNodes.has(node)) {
              return "before";
            }
            if (isMergedClaimNode(customNode) || showLabels) {
              return "after";
            }
            return undefined;
          }}
          nodeCanvasObject={(node, ctx) => {
            paintCovid19Border(node as CustomNode, ctx);
            if (showHighlight && highlightNodes.has(node)) {
              paintRing(node as CustomNode, ctx);
            }
            paintMergedClaimIndicator(node as CustomNode, ctx);
            if (showLabels) {
              renderNodeLabel(node as CustomNode, ctx);
            }
          }}
          linkCanvasObjectMode={() => (showLinkLabels ? "after" : undefined)}
          linkCanvasObject={(link, ctx) => {
            if (showLinkLabels) {
              const label = link.type || "";
              const fontSize = 5;
              const padding = 2;
              ctx.font = `${fontSize}px Sans-Serif`;
              ctx.fillStyle = LABEL_TEXT_COLOR;
              const source =
                typeof link.source !== "string"
                  ? (link.source as CustomNode)
                  : null;
              const target =
                typeof link.target !== "string"
                  ? (link.target as CustomNode)
                  : null;

              if (
                source &&
                target &&
                source.x !== undefined &&
                target.x !== undefined &&
                source.y !== undefined &&
                target.y !== undefined
              ) {
                const textWidth = ctx.measureText(label).width;
                const posX = (source.x + target.x) / 2 - textWidth / 2;
                const posY = (source.y + target.y) / 2;
                const boxWidth = textWidth + padding * 2;
                const boxHeight = fontSize + padding * 2;
                ctx.fillStyle = LABEL_BG_COLOR;
                ctx.fillRect(
                  posX - padding,
                  posY - boxHeight / 2,
                  boxWidth,
                  boxHeight
                );
                ctx.fillStyle = LABEL_TEXT_COLOR;
                ctx.textAlign = "left";
                ctx.textBaseline = "middle";
                ctx.fillText(label, posX, posY);
              }
            }
          }}
          onNodeHover={showHighlight ? handleNodeHover : undefined}
          onLinkHover={showHighlight ? handleLinkHover : undefined}
          onNodeClick={handleNodeClick}
          onLinkClick={handleLinkClick}
          backgroundColor={getBackgroundColor()}
          linkColor={getLinkColor}
        />
      ) : (
        <ForceGraph3D
          ref={graphRef}
          extraRenderers={extraRenderers}
          graphData={graphData}
          {...getGraphNodeColorProps()}
          {...(usesClaimLayout
            ? {
                warmupTicks: 120,
                cooldownTicks: 200,
                d3AlphaDecay: 0.018,
                nodeVal: (node) => getClaimNodeVal(node as CustomNode),
              }
            : {})}
          nodeRelSize={NODE_R}
          linkWidth={getHighlightLinkWidth}
          linkDirectionalParticles={getLinkParticles}
          linkDirectionalParticleWidth={(link) =>
            getLinkParticles(link as CustomLink) > 0 ? 4 : 0
          }
          linkDirectionalArrowLength={getLinkArrowLength}
          linkDirectionalArrowRelPos={1}
          linkDirectionalArrowColor={get3DLinkColor}
          nodeThreeObject={nodeThreeObject}
          nodeThreeObjectExtend={true}
          onNodeHover={showHighlight ? handleNodeHover : undefined}
          onLinkHover={showHighlight ? handleLinkHover : undefined}
          onNodeClick={handleNodeClick}
          onLinkClick={handleLinkClick}
          backgroundColor={getBackgroundColor()}
          linkColor={get3DLinkColor}
          linkThreeObjectExtend={true}
          linkThreeObject={(link) => {
            if (!showLinkLabels) new THREE.Object3D();
            const sprite = new SpriteText(`${link.type}`);
            sprite.color = LABEL_TEXT_COLOR;
            sprite.backgroundColor = LABEL_BG_COLOR;
            sprite.padding = 2;
            sprite.textHeight = 1.5;
            return sprite;
          }}
          linkPositionUpdate={(sprite, { start, end }) => {
            if (!showLinkLabels) return;

            const middlePos = ["x", "y", "z"].reduce((acc, c) => {
              acc[c as keyof Coords] =
                start[c as keyof Coords] +
                (end[c as keyof Coords] - start[c as keyof Coords]) / 2;
              return acc;
            }, {} as Coords);

            // Position sprite
            Object.assign(sprite.position, middlePos);
          }}
        />
      )}
      <Box
        sx={{
          position: "absolute",
          top: 10,
          left: 10,
          zIndex: 1400,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          gap: 1,
        }}
      >
        <Typography variant="body2">Nodes: {nodeCount}</Typography>
        <Typography variant="body2">Relationships: {linkCount}</Typography>
        <Button
          variant="contained"
          onClick={toggleApiDrawer(true)}
          startIcon={<SearchIcon />}
        >
          Ask Query (Local/Global Search)
        </Button>
        <Button
          variant="contained"
          onClick={clearSearchResults}
          startIcon={<DeleteIcon />}
          color="warning"
          disabled={apiSearchResults === null}
        >
          Clear Query Results
        </Button>
      </Box>
      {usesDisplayEntityColors && (
        <Box
          sx={{
            position: "absolute",
            bottom: 16,
            left: 16,
            zIndex: 1400,
            p: 1.5,
            borderRadius: 1,
            backgroundColor: theme.palette.background.paper,
            border: `1px solid ${theme.palette.divider}`,
          }}
        >
          <Typography variant="subtitle1" sx={{ mb: 0.75, fontWeight: 700 }}>
            Entity types
          </Typography>
          {Object.entries(ENTITY_DISPLAY_COLORS).map(([label, color]) => (
            <Box
              key={label}
              sx={{ display: "flex", alignItems: "center", gap: 1, mb: 0.4 }}
            >
              <Box
                sx={{
                  width: 12,
                  height: 12,
                  borderRadius: "50%",
                  backgroundColor: color,
                }}
              />
              <Typography variant="body2" sx={{ fontWeight: 600 }}>
                {label}
              </Typography>
            </Box>
          ))}
        </Box>
      )}
    </Box>
  );
};

export default GraphViewer;
