import React from "react";
import {
  Box,
  Card,
  CardContent,
  Chip,
  Divider,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from "@mui/material";
import { ClaimMergeSource } from "../models/claim-cluster";
import { ClaimPairAuditRow } from "../models/claim-pair-audit";

interface MergedClaimDetailProps {
  clusterSize?: number;
  clusterId?: number;
  sources?: ClaimMergeSource[];
  pairAudits?: ClaimPairAuditRow[];
}

const descriptionForClaimId = (
  claimId: number,
  sources: ClaimMergeSource[]
): string => {
  const source = sources.find((row) => row.human_readable_id === claimId);
  return source?.description ?? `Claim #${claimId}`;
};

const MergedClaimDetail: React.FC<MergedClaimDetailProps> = ({
  clusterSize,
  clusterId,
  sources = [],
  pairAudits = [],
}) => {
  if ((clusterSize ?? 0) <= 1 && sources.length <= 1 && pairAudits.length === 0) {
    return null;
  }

  return (
    <Card sx={{ marginBottom: 3 }}>
      <CardContent>
        <Typography variant="h6" sx={{ fontWeight: "bold", marginBottom: 1 }}>
          Merged claim cluster
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ marginBottom: 2 }}>
          Cluster #{clusterId ?? "?"} · {clusterSize ?? sources.length} source
          claim(s) · {pairAudits.length} verified pair
          {pairAudits.length === 1 ? "" : "s"}
        </Typography>

        {sources.length > 0 && (
          <Box sx={{ marginBottom: 2 }}>
            <Typography variant="subtitle2" sx={{ fontWeight: "bold", mb: 1 }}>
              Source claims
            </Typography>
            <Stack spacing={1.5}>
              {sources.map((source) => (
                <Box
                  key={source.human_readable_id}
                  sx={{
                    border: "1px solid",
                    borderColor: "divider",
                    borderRadius: 1,
                    p: 1.5,
                  }}
                >
                  <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                    <Chip
                      size="small"
                      label={`#${source.human_readable_id}`}
                      variant="outlined"
                    />
                    {source.is_representative && (
                      <Chip size="small" color="primary" label="representative" />
                    )}
                    {source.claim_type && (
                      <Chip size="small" label={source.claim_type} />
                    )}
                  </Stack>
                  <Typography sx={{ mt: 1 }}>{source.description}</Typography>
                  {source.article_title && (
                    <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                      {source.article_title}
                    </Typography>
                  )}
                  {(source.subject_id || source.object_id) && (
                    <Typography variant="body2" sx={{ mt: 0.5 }}>
                      {source.subject_id}
                      {source.subject_id && source.object_id ? " → " : ""}
                      {source.object_id}
                    </Typography>
                  )}
                  {source.source_text && (
                    <Typography
                      variant="body2"
                      color="text.secondary"
                      sx={{ mt: 0.5, fontStyle: "italic" }}
                    >
                      “{source.source_text}”
                    </Typography>
                  )}
                  {!source.is_representative &&
                    source.audit_status &&
                    source.audit_status !== "not_audited" && (
                      <Box sx={{ mt: 1.5 }}>
                        <Divider sx={{ mb: 1 }} />
                        <Stack
                          direction="row"
                          spacing={0.5}
                          flexWrap="wrap"
                          alignItems="center"
                        >
                          <Chip
                            size="small"
                            label={`tradeoff: ${source.overall_tradeoff || "unknown"}`}
                            color={
                              source.audit_status === "failed" ? "error" : "secondary"
                            }
                            variant="outlined"
                          />
                          {source.approach_label && (
                            <Chip
                              size="small"
                              label={`approach: ${source.approach_label}`}
                              color="primary"
                            />
                          )}
                          {(source.change_types ?? []).map((changeType) => (
                            <Chip
                              key={changeType}
                              size="small"
                              label={changeType}
                              variant="outlined"
                            />
                          ))}
                        </Stack>

                        {source.change_rationale && (
                          <Typography variant="body2" sx={{ mt: 1 }}>
                            {source.change_rationale}
                          </Typography>
                        )}
                        {source.approach_rationale && (
                          <Typography
                            variant="body2"
                            color="text.secondary"
                            sx={{ mt: 0.5 }}
                          >
                            Approach: {source.approach_rationale}
                          </Typography>
                        )}

                        {(source.lost_information ?? []).length > 0 && (
                          <Typography variant="body2" color="error" sx={{ mt: 0.75 }}>
                            Lost: {source.lost_information!.join("; ")}
                          </Typography>
                        )}
                        {(source.gained_information ?? []).length > 0 && (
                          <Typography variant="body2" color="success.main" sx={{ mt: 0.75 }}>
                            Gained: {source.gained_information!.join("; ")}
                          </Typography>
                        )}

                        {(source.field_changes ?? []).length > 0 && (
                          <Table size="small" sx={{ mt: 1 }}>
                            <TableHead>
                              <TableRow>
                                <TableCell>Field</TableCell>
                                <TableCell>Operation / effect</TableCell>
                                <TableCell>Source</TableCell>
                                <TableCell>Representative</TableCell>
                              </TableRow>
                            </TableHead>
                            <TableBody>
                              {source.field_changes!.map((change, index) => (
                                <TableRow
                                  key={`${change.field}-${change.operation}-${index}`}
                                >
                                  <TableCell>{change.field}</TableCell>
                                  <TableCell>
                                    {change.operation}
                                    {change.semantic_effect
                                      ? ` · ${change.semantic_effect}`
                                      : ""}
                                  </TableCell>
                                  <TableCell>{change.from || "—"}</TableCell>
                                  <TableCell>{change.to || "—"}</TableCell>
                                </TableRow>
                              ))}
                            </TableBody>
                          </Table>
                        )}
                      </Box>
                    )}
                </Box>
              ))}
            </Stack>
          </Box>
        )}

        {pairAudits.length > 0 && (
          <Box>
            <Divider sx={{ mb: 2 }} />
            <Typography variant="subtitle2" sx={{ fontWeight: "bold", mb: 1 }}>
              Difference categories
            </Typography>
            <Stack spacing={2}>
              {pairAudits.map((audit) => (
                <Box
                  key={`${audit.claim_a_id}-${audit.claim_b_id}`}
                  sx={{
                    border: "1px solid",
                    borderColor: "divider",
                    borderRadius: 1,
                    p: 1.5,
                  }}
                >
                  <Stack direction="row" spacing={1} flexWrap="wrap" alignItems="center">
                    <Typography variant="body2" sx={{ fontWeight: 600 }}>
                      #{audit.claim_a_id} ↔ #{audit.claim_b_id}
                    </Typography>
                    <Chip
                      size="small"
                      label={`sim ${audit.embedding_similarity.toFixed(3)}`}
                      variant="outlined"
                    />
                    <Chip
                      size="small"
                      label={`conf ${audit.confidence.toFixed(2)}`}
                      variant="outlined"
                      color={audit.applied_merge === false ? "default" : "success"}
                    />
                    {audit.applied_merge === false && (
                      <Chip size="small" label="below threshold" variant="outlined" />
                    )}
                  </Stack>

                  <Typography variant="body2" sx={{ mt: 1 }}>
                    {descriptionForClaimId(audit.claim_a_id, sources)}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    vs {descriptionForClaimId(audit.claim_b_id, sources)}
                  </Typography>

                  {(audit.diff_categories ?? audit.diff_types ?? []).length > 0 && (
                    <Stack direction="row" spacing={0.5} flexWrap="wrap" sx={{ mt: 1 }}>
                      {(audit.diff_categories ?? audit.diff_types ?? []).map((category) => (
                        <Chip
                          key={category}
                          size="small"
                          label={category}
                          color="secondary"
                          variant="outlined"
                        />
                      ))}
                    </Stack>
                  )}

                  {audit.rationale && (
                    <Typography variant="body2" sx={{ mt: 1 }}>
                      {audit.rationale}
                    </Typography>
                  )}

                  {audit.field_diffs.length > 0 && (
                    <Table size="small" sx={{ mt: 1 }}>
                      <TableHead>
                        <TableRow>
                          <TableCell>Field</TableCell>
                          <TableCell>Kind</TableCell>
                          <TableCell>Claim A</TableCell>
                          <TableCell>Claim B</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {audit.field_diffs.map((diff, index) => (
                          <TableRow key={`${diff.field}-${diff.kind}-${index}`}>
                            <TableCell>{diff.field}</TableCell>
                            <TableCell>{diff.kind}</TableCell>
                            <TableCell>{diff.claim_a ?? "—"}</TableCell>
                            <TableCell>{diff.claim_b ?? "—"}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  )}
                </Box>
              ))}
            </Stack>
          </Box>
        )}
      </CardContent>
    </Card>
  );
};

export default MergedClaimDetail;
