import { parquetRead, ParquetReadOptions } from "hyparquet";

export class AsyncBuffer {
  private buffer: ArrayBuffer;

  constructor(buffer: ArrayBuffer) {
    this.buffer = buffer;
  }

  async slice(start: number, end: number): Promise<ArrayBuffer> {
    return this.buffer.slice(start, end);
  }

  get byteLength() {
    return this.buffer.byteLength;
  }
}

const parseValue = (value: any, type: "number" | "bigint"): any => {
  if (typeof value === "string" && value.endsWith("n")) {
    return BigInt(value.slice(0, -1));
  }
  return type === "bigint" ? BigInt(value) : Number(value);
};

const parseStringList = (value: unknown): string[] => {
  if (value == null) return [];
  if (Array.isArray(value)) return value.map(String);
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parsed.map(String);
    } catch {
      return [trimmed];
    }
  }
  return [String(value)];
};

const parseFieldDiffs = (value: unknown) => {
  if (value == null) return [];
  let items: unknown[] = [];
  if (Array.isArray(value)) {
    items = value;
  } else if (typeof value === "string") {
    try {
      items = JSON.parse(value);
    } catch {
      return [];
    }
  }
  if (!Array.isArray(items)) return [];
  return items
    .filter((item) => item && typeof item === "object")
    .map((item) => {
      const row = item as Record<string, unknown>;
      return {
        field: String(row.field ?? ""),
        kind: String(row.kind ?? ""),
        claim_a: row.claim_a != null ? String(row.claim_a) : undefined,
        claim_b: row.claim_b != null ? String(row.claim_b) : undefined,
      };
    });
};

const parseFieldChanges = (value: unknown) => {
  if (value == null) return [];
  let items: unknown[] = [];
  if (Array.isArray(value)) {
    items = value;
  } else if (typeof value === "string") {
    try {
      items = JSON.parse(value);
    } catch {
      return [];
    }
  }
  if (!Array.isArray(items)) return [];
  return items
    .filter((item) => item && typeof item === "object")
    .map((item) => {
      const row = item as Record<string, unknown>;
      return {
        field: String(row.field ?? ""),
        from: String(row.from ?? ""),
        to: String(row.to ?? ""),
        operation: String(row.operation ?? ""),
        semantic_effect: String(row.semantic_effect ?? ""),
      };
    });
};

const parseConfidence = (value: unknown): number => {
  if (typeof value === "number") return value;
  if (typeof value === "string") {
    const text = value.trim().toLowerCase();
    const legacy: Record<string, number> = {
      low: 0.3,
      medium: 0.6,
      high: 0.9,
    };
    if (text in legacy) return legacy[text];
    const parsed = Number(text);
    return Number.isFinite(parsed) ? parsed : 0;
  }
  return 0;
};

const parseBoolean = (value: unknown): boolean => {
  if (typeof value === "boolean") return value;
  if (typeof value === "string") {
    return value.toLowerCase() === "true" || value === "1";
  }
  return Boolean(value);
};

export const readParquetFile = async (
  file: File | Blob,
  schema?: string
): Promise<any[]> => {
  try {
    const arrayBuffer = await file.arrayBuffer();
    const asyncBuffer = new AsyncBuffer(arrayBuffer);

    return new Promise((resolve, reject) => {
      const options: ParquetReadOptions = {
        file: asyncBuffer,
        rowFormat: 'object',
        onComplete: (rows: Record<string, any>[]) => {          
          if (schema === "entity") {
            
            resolve(
              rows.map((row) => ({         
                id: row["id"],                
                human_readable_id: parseValue(row["human_readable_id"], "number"),
                title: row["title"],
                type: row["type"],
                description: row["description"],
                text_unit_ids: row["text_unit_ids"],

              }))
            );
          } else if (schema === "relationship") {
            resolve(
              rows.map((row) => ({
                id: row["id"],
                human_readable_id: parseValue(row["human_readable_id"], "number"),                
                source: row["source"],
                target: row["target"],
                description: row["description"],
                weight: row["weight"],
                combined_degree: parseValue(row["combined_degree"], "number"),                
                text_unit_ids: row["text_unit_ids"],
                // Use the relation type from the parquet (e.g. ENTAILS, TEMPORAL,
                // PARAPHRASE); fall back to "RELATED" only when absent.
                type: row["type"] ?? "RELATED",
              }))
            );
          } else if (schema === "document") {
            resolve(
              rows.map((row) => ({
                id: row["id"],
                human_readable_id: parseValue(row["human_readable_id"], "number"),                
                title: row["title"],
                text: row["text"],
                text_unit_ids: row["text_unit_ids"],           
              }))
            );
          } else if (schema === "text_unit") {
            resolve(
              rows.map((row) => ({
                id: row["id"],
                human_readable_id: parseValue(row["human_readable_id"], "number"),                
                text: row["text"],
                n_tokens: parseValue(row["n_tokens"], "number"),                
                document_ids: row["document_ids"],
                entity_ids: row["entity_ids"],
                relationship_ids: row["relationship_ids"],
              }))
            );
          } else if (schema === "community") {
            resolve(
              rows.map((row) => ({
                id: row["id"],
                human_readable_id: parseValue(row["human_readable_id"], "number"),     
                community: parseValue(row["community"], "number"),
                parent: parseValue(row["parent"], "number"),                
                level: parseValue(row["level"], "number"),                
                title: row["title"],
                entity_ids: row["entity_ids"],
                relationship_ids: row["relationship_ids"],
                text_unit_ids: row["text_unit_ids"],
                period: row["period"],                
                size: parseValue(row["size"], "number"),
              }))
            );
          } else if (schema === "community_report") {
            resolve(
              rows.map((row) => ({
                id: row["id"],
                human_readable_id: parseValue(row["human_readable_id"], "number"),
                community: parseValue(row["community"], "number"),       
                parent: parseValue(row["parent"], "number"),
                level: parseValue(row["level"], "number"),                
                title: row["title"],
                summary: row["summary"],
                full_content: row["full_content"],
                rank: row["rank"],
                rank_explanation: row["rank_explanation"],
                findings: row["findings"],
                full_content_json: row["full_content_json"],
                period: row["period"],                
                size: parseValue(row["size"], "number"),            
              }))
            );
          } else if (schema === "covariate") {
            resolve(
              rows.map((row) => ({
                id: row["id"],
                human_readable_id: parseValue(row["human_readable_id"], "number"),                
                covariate_type: row["covariate_type"],
                type: row["type"],
                description: row["description"],
                subject_id: row["subject_id"],
                object_id: row["object_id"],
                status: row["status"],
                start_date: row["start_date"],
                end_date: row["end_date"],
                source_text: row["source_text"],
                text_unit_id: row["text_unit_id"],              
              }))
            );
          } else if (schema === "claim_cluster") {
            resolve(
              rows.map((row) => ({
                human_readable_id: parseValue(row["human_readable_id"], "number"),
                cluster_id: parseValue(row["cluster_id"], "number"),
                cluster_size: parseValue(row["cluster_size"], "number"),
                representative_id: parseValue(row["representative_id"], "number"),
                max_similarity_in_cluster: row["max_similarity_in_cluster"],
                change_types: parseStringList(row["change_types"]),
                field_changes: parseFieldChanges(row["field_changes"]),
                overall_tradeoff: String(row["overall_tradeoff"] ?? ""),
                lost_information: parseStringList(row["lost_information"]),
                gained_information: parseStringList(row["gained_information"]),
                change_rationale: String(row["change_rationale"] ?? ""),
                audit_status: String(row["audit_status"] ?? ""),
                change_cached: parseBoolean(row["change_cached"]),
                approach_id: String(row["approach_id"] ?? ""),
                approach_label: String(row["approach_label"] ?? ""),
                approach_rationale: String(row["approach_rationale"] ?? ""),
                approach_status: String(row["approach_status"] ?? ""),
                approach_taxonomy_version: String(
                  row["approach_taxonomy_version"] ?? ""
                ),
              }))
            );
          } else if (schema === "claim_pair_audit") {
            resolve(
              rows.map((row) => ({
                claim_a_id: parseValue(row["claim_a_id"], "number"),
                claim_b_id: parseValue(row["claim_b_id"], "number"),
                embedding_similarity: parseValue(row["embedding_similarity"], "number"),
                same_claim: parseBoolean(row["same_claim"]),
                confidence: parseConfidence(row["confidence"]),
                rationale: String(row["rationale"] ?? ""),
                diff_categories: parseStringList(
                  row["diff_categories"] ?? row["diff_types"]
                ),
                diff_types: parseStringList(
                  row["diff_categories"] ?? row["diff_types"]
                ),
                field_diffs: parseFieldDiffs(row["field_diffs"]),
                structural_diff_fields: parseStringList(row["structural_diff_fields"]),
                cached: parseBoolean(row["cached"]),
                applied_merge: row["applied_merge"] == null
                  ? undefined
                  : parseBoolean(row["applied_merge"]),
              }))
            );
          } else {
            resolve(
              rows.map((row: Record<string, any>) => ({
                ...row
              }))
            );
          }
        },
      };
      parquetRead(options).catch(reject);
    });
  } catch (err) {
    console.error("Error reading Parquet file", err);
    return [];
  }
};
