import { ClaimClusterRow, ClaimMergeMeta, ClaimMergeSource } from "../models/claim-cluster";
import { ClaimPairAuditRow } from "../models/claim-pair-audit";
import { Covariate } from "../models/covariate";
import { Document } from "../models/document";
import { TextUnit } from "../models/text-unit";

const textUnitToDocumentTitle = (
  textUnitId: string | undefined,
  textunits: TextUnit[],
  documents: Document[]
): string | undefined => {
  if (!textUnitId) return undefined;
  const tu = textunits.find((row) => row.id === textUnitId);
  if (!tu?.document_ids?.length) return undefined;
  const docId = String(tu.document_ids[0]);
  const doc = documents.find(
    (row) => String(row.id) === docId || String(row.human_readable_id) === docId
  );
  return doc?.title;
};

export const buildClaimMergeMeta = (
  clusters: ClaimClusterRow[],
  covariates: Covariate[],
  documents: Document[],
  textunits: TextUnit[],
  pairAudits: ClaimPairAuditRow[] = []
): Map<number, ClaimMergeMeta> => {
  const covById = new Map(
    covariates.map((row) => [row.human_readable_id, row])
  );
  const byCluster = new Map<number, ClaimClusterRow[]>();

  clusters.forEach((row) => {
    const list = byCluster.get(row.cluster_id) ?? [];
    list.push(row);
    byCluster.set(row.cluster_id, list);
  });

  const result = new Map<number, ClaimMergeMeta>();

  byCluster.forEach((members, clusterId) => {
    const clusterSize = members[0]?.cluster_size ?? members.length;
    const sources: ClaimMergeSource[] = members
      .map((member) => {
        const cov = covById.get(member.human_readable_id);
        return {
          human_readable_id: member.human_readable_id,
          description: cov?.description ?? "",
          subject_id: cov?.subject_id,
          object_id: cov?.object_id,
          claim_type: cov?.type,
          source_text: cov?.source_text,
          article_title: textUnitToDocumentTitle(
            cov?.text_unit_id,
            textunits,
            documents
          ),
          is_representative:
            member.human_readable_id === member.representative_id,
          similarity: member.max_similarity_in_cluster,
          change_types: member.change_types,
          field_changes: member.field_changes,
          overall_tradeoff: member.overall_tradeoff,
          lost_information: member.lost_information,
          gained_information: member.gained_information,
          change_rationale: member.change_rationale,
          audit_status: member.audit_status,
          approach_id: member.approach_id,
          approach_label: member.approach_label,
          approach_rationale: member.approach_rationale,
          approach_status: member.approach_status,
          approach_taxonomy_version: member.approach_taxonomy_version,
        };
      })
      .sort((a, b) => a.human_readable_id - b.human_readable_id);

    const memberIds = new Set(sources.map((source) => source.human_readable_id));
    const clusterAudits = pairAudits.filter((row) => {
      if (!memberIds.has(row.claim_a_id) || !memberIds.has(row.claim_b_id)) {
        return false;
      }
      if (!row.same_claim) return false;
      if (row.applied_merge != null) return row.applied_merge;
      return true;
    });

    result.set(clusterId, {
      cluster_id: clusterId,
      cluster_size: clusterSize,
      sources,
      pair_audits: clusterAudits,
    });
  });

  return result;
};

export const isMergedClaimNode = (node: {
  merge_cluster_size?: number;
}): boolean => (node.merge_cluster_size ?? 0) > 1;
