export const CLAIM_VIEWS = ["original", "merged"] as const;
export type ClaimView = (typeof CLAIM_VIEWS)[number];

export const CLAIM_DATASETS: Record<ClaimView, string> = {
  original: "claims-original",
  merged: "claims-merged",
};

export const claimGraphPath = (view: ClaimView) => `/claims/${view}`;
export const claimDataPath = (view: ClaimView) => `/claims/${view}/data`;

export const claimViewFromPath = (pathname: string): ClaimView | null => {
  if (
    pathname === claimGraphPath("original") ||
    pathname === claimDataPath("original")
  ) {
    return "original";
  }
  if (
    pathname === claimGraphPath("merged") ||
    pathname === claimDataPath("merged")
  ) {
    return "merged";
  }
  return null;
};

export const isClaimDataPath = (pathname: string) =>
  CLAIM_VIEWS.some((view) => pathname === claimDataPath(view));

export const datasetForClaimView = (view: ClaimView) => CLAIM_DATASETS[view];
