import React, { useState, useEffect, useCallback } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import GraphViewer from "./GraphViewer";
import ClaimViewSwitcher from "./ClaimViewSwitcher";
import { Box, Container, Tab, Tabs } from "@mui/material";
import { useDropzone } from "react-dropzone";
import DropZone from "./DropZone";
import Introduction from "./Introduction";
import useFileHandler from "../hooks/useFileHandler";
import useGraphData from "../hooks/useGraphData";
import DataTableContainer, { DataTableName } from "./DataTableContainer";
import ReactGA from "react-ga4";
import {
  claimDataPath,
  claimGraphPath,
  claimViewFromPath,
  datasetForClaimView,
  isClaimDataPath,
} from "../utils/claim-routes";

const CLAIM_DATASETS = new Set(["claims-original", "claims-merged"]);
const GRAPH_ROUTE_DATASETS: Record<string, string> = {
  "/entities": "new_all_qwen_36",
  "/fake": "fake",
  "/real": "real",
};

const GraphDataHandler: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();

  const [tabIndex, setTabIndex] = useState(0);
  const [graphType, setGraphType] = useState<"2d" | "3d">("2d");
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [selectedTable, setSelectedTable] =
    useState<DataTableName>("entities");
  const [includeDocuments, setIncludeDocuments] = useState(false);
  const [includeTextUnits, setIncludeTextUnits] = useState(false);
  const [includeCommunities, setIncludeCommunities] = useState(false);
  const [includeCovariates, setIncludeCovariates] = useState(false);
  const [minConnections, setMinConnections] = useState(0);

  const {
    entities,
    relationships,
    documents,
    textunits,
    communities,
    covariates,
    claimClusters,
    claimPairAudit,
    communityReports,
    handleFilesRead,
    loadDefaultFiles,
    loadArtifactsFromDir,
  } = useFileHandler();

  const graphData = useGraphData(
    entities,
    relationships,
    documents,
    textunits,
    communities,
    communityReports,
    covariates,
    claimClusters,
    claimPairAudit,
    includeDocuments,
    includeTextUnits,
    includeCommunities,
    includeCovariates,
    minConnections
  );

  const hasDocuments = documents.length > 0;
  const hasTextUnits = textunits.length > 0;
  const hasCommunities = communities.length > 0;
  const hasCovariates = covariates.length > 0;

  const claimView = claimViewFromPath(location.pathname);
  const graphPath = claimView
    ? claimGraphPath(claimView)
    : GRAPH_ROUTE_DATASETS[location.pathname]
      ? location.pathname
      : "/entities";

  const loadClaimDataset = useCallback(
    async (view: NonNullable<typeof claimView>) => {
      const dataset = datasetForClaimView(view);
      const loaded = await loadArtifactsFromDir(
        `${process.env.PUBLIC_URL}/artifacts/${dataset}`,
        { navigateTo: false }
      );
      if (loaded) {
        setMinConnections(0);
      }
      return loaded;
    },
    [loadArtifactsFromDir]
  );

  useEffect(() => {
    const view = claimViewFromPath(location.pathname);
    if (view) {
      setTabIndex(isClaimDataPath(location.pathname) ? 2 : 1);
      loadClaimDataset(view);
      return;
    }

    const graphDataset = GRAPH_ROUTE_DATASETS[location.pathname];
    if (graphDataset) {
      setTabIndex(1);
      loadArtifactsFromDir(`${(process.env.PUBLIC_URL || "").replace(/\/$/, "")}/artifacts/${graphDataset}`, {
        navigateTo: false,
      }).then((loaded) => {
        setMinConnections(loaded ? 15 : 0);
      });
      return;
    }

    const params = new URLSearchParams(location.search);
    const dataset = params.get("dataset") ?? undefined;
    if (location.pathname === "/graph" || dataset) {
      loadDefaultFiles(dataset).then((loaded) => {
        setMinConnections(
          loaded && CLAIM_DATASETS.has(loaded) ? 0 : 15
        );
      });
    }
    // eslint-disable-next-line
  }, [location.pathname, location.search]);

  useEffect(() => {
    const measurementId = process.env.REACT_APP_GA_MEASUREMENT_ID;
    if (measurementId) {
      ReactGA.initialize(measurementId);
    } else {
      console.error("Google Analytics measurement ID not found");
    }
  }, []);

  useEffect(() => {
    const view = claimViewFromPath(location.pathname);
    if (view) {
      setTabIndex(isClaimDataPath(location.pathname) ? 2 : 1);
      return;
    }

    switch (location.pathname) {
      case "/upload":
        setTabIndex(0);
        break;
      case "/graph":
      case "/entities":
      case "/fake":
      case "/real":
        setTabIndex(1);
        break;
      case "/data":
        setTabIndex(2);
        break;
      default:
        setTabIndex(0);
    }
  }, [location.pathname]);

  const onDrop = (acceptedFiles: File[]) => {
    handleFilesRead(acceptedFiles);
    navigate(graphPath, { replace: true });
  };

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    noClick: false,
    noKeyboard: true,
    accept: {
      "application/x-parquet": [".parquet"],
    },
  });

  const handleChange = (event: React.ChangeEvent<{}>, newValue: number) => {
    setTabIndex(newValue);
    if (newValue === 2 && claimClusters.length > 0) {
      setSelectedTable("claimClusters");
    }
    let path = "/upload";
    if (newValue === 1) path = graphPath;
    if (newValue === 2) path = claimView ? claimDataPath(claimView) : "/data";
    navigate(path);
    ReactGA.send({
      hitType: "event",
      eventCategory: "Tabs",
      eventAction: "click",
      eventLabel: `Tab ${newValue}`,
    });
  };

  const toggleGraphType = () => {
    setGraphType((prevType) => (prevType === "2d" ? "3d" : "2d"));
  };

  const toggleFullscreen = () => {
    setIsFullscreen(!isFullscreen);
  };

  return (
    <>
      <Tabs value={tabIndex} onChange={handleChange} centered>
        <Tab label="Upload Artifacts" />
        <Tab label="Graph Visualization" />
        <Tab label="Data Tables" />
      </Tabs>
      {tabIndex === 0 && (
        <Container
          maxWidth="md"
          sx={{
            mt: 3,
            display: "flex",
            flexDirection: "column",
          }}
        >
          <DropZone {...{ getRootProps, getInputProps, isDragActive }} />
          <Introduction />
        </Container>
      )}
      {tabIndex === 1 && (
        <Box
          p={3}
          sx={{
            height: isFullscreen ? "100vh" : "calc(100vh - 64px)",
            width: isFullscreen ? "100vw" : "100%",
            position: isFullscreen ? "fixed" : "relative",
            top: 0,
            left: 0,
            zIndex: isFullscreen ? 1300 : "auto",
            overflow: "hidden",
          }}
        >
          <ClaimViewSwitcher
            pathname={location.pathname}
            nodeCount={entities.length}
          />
          <GraphViewer
            data={graphData}
            graphType={graphType}
            isFullscreen={isFullscreen}
            onToggleFullscreen={toggleFullscreen}
            onToggleGraphType={toggleGraphType}
            includeDocuments={includeDocuments}
            includeTextUnits={includeTextUnits}
            onIncludeDocumentsChange={() =>
              setIncludeDocuments(!includeDocuments)
            }
            onIncludeTextUnitsChange={() =>
              setIncludeTextUnits(!includeTextUnits)
            }
            includeCommunities={includeCommunities}
            onIncludeCommunitiesChange={() =>
              setIncludeCommunities(!includeCommunities)
            }
            includeCovariates={includeCovariates}
            onIncludeCovariatesChange={() =>
              setIncludeCovariates(!includeCovariates)
            }
            hasDocuments={hasDocuments}
            hasTextUnits={hasTextUnits}
            hasCommunities={hasCommunities}
            hasCovariates={hasCovariates}
            minConnections={minConnections}
            onMinConnectionsChange={setMinConnections}
            totalEntities={entities.length}
          />
        </Box>
      )}

      {tabIndex === 2 && (
        <Box sx={{ display: "flex", height: "calc(100vh - 64px)" }}>
          <DataTableContainer
            selectedTable={selectedTable}
            setSelectedTable={setSelectedTable}
            entities={entities}
            relationships={relationships}
            documents={documents}
            textunits={textunits}
            communities={communities}
            communityReports={communityReports}
            covariates={covariates}
            claimClusters={claimClusters}
            claimPairAudit={claimPairAudit}
          />
        </Box>
      )}
    </>
  );
};

export default GraphDataHandler;
