import { MRT_ColumnDef } from "material-react-table";

export interface ClaimFieldDiff {
  field: string;
  kind: string;
  claim_a?: string;
  claim_b?: string;
}

export interface ClaimPairAuditRow {
  claim_a_id: number;
  claim_b_id: number;
  embedding_similarity: number;
  same_claim: boolean;
  confidence: number;
  rationale: string;
  diff_categories: string[];
  /** @deprecated legacy column name; same as diff_categories */
  diff_types?: string[];
  field_diffs: ClaimFieldDiff[];
  structural_diff_fields: string[];
  cached?: boolean;
  applied_merge?: boolean;
}

const jsonCell = ({ renderedCellValue }: { renderedCellValue: unknown }) =>
  Array.isArray(renderedCellValue) || typeof renderedCellValue === "object"
    ? JSON.stringify(renderedCellValue)
    : renderedCellValue;

export const claimPairAuditColumns: MRT_ColumnDef<ClaimPairAuditRow>[] = [
  { accessorKey: "claim_a_id", header: "claim_a_id" },
  { accessorKey: "claim_b_id", header: "claim_b_id" },
  { accessorKey: "embedding_similarity", header: "embedding_similarity" },
  { accessorKey: "same_claim", header: "same_claim" },
  { accessorKey: "confidence", header: "confidence" },
  { accessorKey: "applied_merge", header: "applied_merge" },
  { accessorKey: "diff_categories", header: "diff_categories", Cell: jsonCell },
  {
    accessorKey: "structural_diff_fields",
    header: "structural_diff_fields",
    Cell: jsonCell,
  },
  { accessorKey: "field_diffs", header: "field_diffs", Cell: jsonCell },
  { accessorKey: "rationale", header: "rationale" },
  { accessorKey: "cached", header: "cached" },
];
