import { CustomNode } from "../models/custom-graph-data";

/** Paper-style entity display categories. */
export const ENTITY_DISPLAY_COLORS: Record<string, string> = {
  Person: "#1f77b4",
  Organization: "#8c564b",
  Disease: "#d62728",
  Entity: "#7f7f7f",
  Location: "#40E0D0",
  Authority: "#ff7f0e",
};

const DISPLAY_TYPES = new Set(Object.keys(ENTITY_DISPLAY_COLORS));

export const isDisplayEntityType = (type: string | undefined): boolean =>
  !!type && DISPLAY_TYPES.has(type);

export const getEntityNodeColor = (node: CustomNode): string =>
  ENTITY_DISPLAY_COLORS[node.type] ?? ENTITY_DISPLAY_COLORS.Entity;

const GENERAL_TYPE_PALETTE = [
  "#1f77b4",
  "#ff7f0e",
  "#2ca02c",
  "#d62728",
  "#9467bd",
  "#8c564b",
  "#e377c2",
  "#7f7f7f",
  "#bcbd22",
  "#17becf",
  "#4e79a7",
  "#f28e2b",
  "#e15759",
  "#76b7b2",
  "#59a14f",
  "#edc948",
  "#b07aa1",
  "#ff9da7",
  "#9c755f",
  "#bab0ac",
];

const normalizeGeneralType = (type: string | undefined): string =>
  (type || "").trim().toUpperCase().replace(/\s+/g, " ");

const hashString = (value: string): number => {
  let hash = 0;
  for (let i = 0; i < value.length; i += 1) {
    hash = (hash * 31 + value.charCodeAt(i)) >>> 0;
  }
  return hash;
};

export const getGeneralTypeColor = (type: string | undefined): string => {
  const normalized = normalizeGeneralType(type);
  if (!normalized) return ENTITY_DISPLAY_COLORS.Entity;
  return GENERAL_TYPE_PALETTE[hashString(normalized) % GENERAL_TYPE_PALETTE.length];
};

/** Highlight the canonical COVID-19 disease node (exact title match). */
export const isCovid19Entity = (node: CustomNode): boolean => {
  const title = (node.title || node.name || node.id || "").trim();
  return title.toUpperCase() === "COVID-19";
};
